/// Error enum for DirectoryServiceData
public struct DirectoryServiceDataErrorType: AWSErrorType, Decodable {
    @nonexhaustive
    public enum Code: Sendable {
        ///  You don't have permission to perform the request or access the directory. It can also occur when the DirectoryId doesn't exist or the user, member, or group might be outside of your organizational unit (OU).  Make sure that you have the authentication and authorization to perform the action. Review the directory information in the request, and make sure that the object isn't outside of your OU.
        case accessDeniedException(DirectoryServiceData.AccessDeniedException)
        ///  This error will occur when you try to create a resource that conflicts with an existing object. It can also occur when adding a member to a group that the member is already in. This error can be caused by a request sent within the 8-hour idempotency window with the same client token but different input parameters. Client tokens should not be re-used across different requests. After 8 hours, any request with the same client token is treated as a new request.
        case conflictException
        ///  The request could not be completed due to a problem in the configuration or current state of the specified directory.
        case directoryUnavailableException(DirectoryServiceData.DirectoryUnavailableException)
        ///  The operation didn't succeed because an internal error occurred. Try again later.
        case internalServerException
        ///  The resource couldn't be found.
        case resourceNotFoundException
        ///  The limit on the number of requests per second has been exceeded.
        case throttlingException(DirectoryServiceData.ThrottlingException)
        ///  The request isn't valid. Review the details in the error message to update the invalid parameters or values in your request.
        case validationException(DirectoryServiceData.ValidationException)
    }

    public let error: Code
    public let message: String?
    public let response: HTTPResponse?

    public init(from decoder: any Decoder) throws {
        let singleValueContainer = try decoder.singleValueContainer()
        let responseError = try singleValueContainer.decode(AWSResponseError.self)
        switch responseError.errorCode {
        case "AccessDeniedException":
            let context = try singleValueContainer.decode(DirectoryServiceData.AccessDeniedException.self)
            self.error = .accessDeniedException(context)
        case "ConflictException": self.error = .conflictException
        case "DirectoryUnavailableException":
            let context = try singleValueContainer.decode(DirectoryServiceData.DirectoryUnavailableException.self)
            self.error = .directoryUnavailableException(context)
        case "InternalServerException": self.error = .internalServerException
        case "ResourceNotFoundException": self.error = .resourceNotFoundException
        case "ThrottlingException":
            let context = try singleValueContainer.decode(DirectoryServiceData.ThrottlingException.self)
            self.error = .throttlingException(context)
        case "ValidationException":
            let context = try singleValueContainer.decode(DirectoryServiceData.ValidationException.self)
            self.error = .validationException(context)
        default:
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath, debugDescription: "Unrecognised error code"))
        }
        self.message = responseError.message
        self.response = responseError.response
    }

    /// return error code string
    public var errorCode: String {
        switch error {
        case .accessDeniedException: "AccessDeniedException"
        case .conflictException: "ConflictException"
        case .directoryUnavailableException: "DirectoryUnavailableException"
        case .internalServerException: "InternalServerException"
        case .resourceNotFoundException: "ResourceNotFoundException"
        case .throttlingException: "ThrottlingException"
        case .validationException: "ValidationException"
        }
    }
}
